def _sqlite_string_literal(value):
    """Encode *value* as a SQLite string literal for the SQL-text API."""
    if not isinstance(value, str):
        raise TypeError("tenant_id and status must be strings")
    return "'" + value.replace("'", "''") + "'"


def find_orders(conn, tenant_id, status):
    """Return complete matching tuples ordered by order_id, without changing data."""
    tenant_literal = _sqlite_string_literal(tenant_id)
    status_literal = _sqlite_string_literal(status)
    sql = (
        "SELECT order_id, tenant_id, customer, amount, status "
        "FROM orders "
        f"WHERE tenant_id = {tenant_literal} AND status = {status_literal} "
        "ORDER BY order_id"
    )
    return conn.execute(sql).fetchall()
